]

# List all 3s
print("All 3s:")
for r in range(13):
    for c in range(15):
        if test_in[r][c] == 3:
            # Check neighbors
            neighs = set()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 13 and 0 <= nc < 15:
                    neighs.add(test_in[nr][nc])
            print(f"  ({r},{c}): neighbors={neighs}, should become 6 if next to 6, or 2 otherwise")

# List all special cells (0,1,4,7)
print("\nAll special cells (0,1,4,7):")
for r in range(13):
    for c in range(15):
        if test_in[r][c] in [0,1,4,7]:
            neighs = set()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 13 and 0 <= nc < 15:
                    neighs.add(test_in[nr][nc])
            unique_neighs = neighs - {test_in[r][c]}
            print(f"  ({r},{c}): value={test_in[r][c]}, neighbors={unique_neighs}")

